<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { post, api } from '../api/client'
import { useIdentity } from '../stores/identity'
const identity = useIdentity(), router = useRouter()
const opened = ref(false), admin = ref(false), error = ref(''), success = ref(''), busy = ref(false)
const current = ref(''), password = ref('')
const resetAccount = ref(''), resetPassword = ref('')
const staff = ref({ username: '', display_name: '', password: '' })
onMounted(async () => { try { admin.value = (await api<{ manage_staff: boolean }>('/auth/capabilities')).manage_staff } catch { /* Account form still available. */ } })
async function change() { busy.value = true; error.value = ''; try { await post('/auth/change-password', { current_password: current.value, password: password.value }); identity.clear(); await router.replace('/login') } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
async function create() { busy.value = true; error.value = ''; try { success.value = (await post<{ message: string }>('/staff/accounts', { ...staff.value, display_name: staff.value.display_name || undefined })).message; staff.value = { username: '', display_name: '', password: '' } } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
async function reset() { busy.value = true; error.value = ''; success.value = ''; try { success.value = (await post<{ message: string }>('/staff/accounts/reset-password', { username: resetAccount.value.trim(), password: resetPassword.value })).message; const ownAccount = resetAccount.value.trim() === identity.actor?.username; resetPassword.value = ''; resetAccount.value = ''; if (ownAccount) { identity.clear(); await router.replace('/login') } } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
</script>
<template><el-button text @click="opened = true">账号设置</el-button><el-dialog v-model="opened" title="账号设置" width="min(480px, 94vw)"><form class="account-form" @submit.prevent="change"><h3>修改密码</h3><el-input v-model="current" type="password" show-password placeholder="当前密码" aria-label="当前密码" autocomplete="current-password" /><el-input v-model="password" type="password" show-password placeholder="新密码（至少 10 位）" aria-label="新密码" autocomplete="new-password" /><el-button type="primary" :loading="busy" :disabled="password.length < 10 || !current" native-type="submit">修改并重新登录</el-button></form><form v-if="admin" class="account-form" @submit.prevent="create"><h3>创建客服账号</h3><el-input v-model="staff.username" placeholder="账号（3–32 位字母、数字）" aria-label="客服账号" /><el-input v-model="staff.display_name" placeholder="姓名" aria-label="客服姓名" /><el-input v-model="staff.password" type="password" show-password placeholder="初始密码（至少 10 位）" aria-label="客服初始密码" /><el-button :loading="busy" native-type="submit">创建客服账号</el-button></form><form v-if="admin" class="account-form" @submit.prevent="reset"><h3>重置账号密码</h3><p class="muted">核实本人请求后，设置新密码。该账号的已有登录将失效。</p><el-input v-model="resetAccount" placeholder="需要重置的账号" aria-label="重置账号" /><el-input v-model="resetPassword" type="password" show-password placeholder="新密码（至少 10 位）" aria-label="重置账号的新密码" autocomplete="new-password" /><el-button :loading="busy" :disabled="!resetAccount.trim() || resetPassword.length < 10" native-type="submit">重置密码</el-button></form><p v-if="error" role="alert" class="error-text">{{ error }}</p><p v-if="success">{{ success }}</p></el-dialog></template>
